rejected_proposal_sources.adaptive_offline.gd:
extends RefCounted

# ISOLATED EXPERIMENT. Nothing in production preloads or calls this class.
# Step doubling estimates the error of the existing ordered update map. It is
# not a proof of accuracy relative to repeated 0.1 s updates: audit that separately.
const Metrics = preload("res://tests/experimental/adaptive_metrics.gd")
const Checkpoint = preload("res://tests/experimental/continuous_checkpoint.gd")
const REFERENCE_STEP: float = TimeManager.OFFLINE_MAX_GAME_STEP

var maximum_step: float = 60.0
var minimum_step: float = REFERENCE_STEP
var absolute_tolerance: float = 1e-8
var relative_tolerance: float = 1e-4
var event_safety_margin: float = 0.1
var fallback_window_ticks: int = 10
var audit_interval: float = 60.0
var distribute_error_budget: bool = true
var force_exact: bool = false
var allow_environmental_feedback: bool = true
# Diagnostics are optional: per-attempt traces are excluded from throughput runs.
var numerical_retry_max_ticks: int = 0
var trial_failure_reason: String = ""
var trace_attempts: bool = false
var attempts: Array[Dictionary] = []
var preserve_proposal_at_audit: bool = false
var profile_checkpoints: bool = false

var counters: Dictionary = {}
var samples: Dictionary = {}
var simulation: Simulation
var manager: TimeManager
var elapsed: float = 0.0
var duration: float = 0.0

func _init(game_simulation: Simulation) -> void:
	simulation = game_simulation
	manager = TimeManager.new(simulation)


# There are no generator-specific shortcuts. Consumers, discrete production,
# stateful/dormancy modifiers and discrete controllers deliberately fall back.
func guard() -> String:
	var state: GameState = simulation.state
	if force_exact:
		return "forced_exact"
	if not allow_environmental_feedback and (state.get_heat_leak_per_second() > 0.0 or state.get_matter_decay_per_second() > 0.0):
		return "environmental_feedback"
	if simulation.profiling_enabled or simulation.diagnostics_enabled:
		return "instrumented_simulation"
	if state.prestige_planning:
		return "prestige_planning"
	for automation in [state.generator_automation_manager, state.upgrade_automation_manager]:
		for entry in automation.automation_states.values():
			if entry["enabled"]:
				return "enabled_automation"
	var changing: Dictionary = {}
	for g in state.generators.values():
		if g.cycle_active or g.auto_run_cycles:
			return "cycle_or_auto_run"
		if g.definition.cycle_based:
			continue
		if not g.unlocked:
			continue
		# Throttle flags can change even for paused/level-zero consumers.
		if not g.get_active_inputs().is_empty():
			return "resource_consumers"
		if g.manually_paused and g.operating:
			return "pause_transition"
		if g.manually_paused or g.level <= 0:
			continue
		if not g.operating or g.is_throttled:
			return "operating_transition"
		for modifier in g.modifiers:
			if modifier.dynamic and modifier.dynamic_formula == Modifier.DYNAMIC_LAVA_MITE_DORMANCY:
				return "time_dependent_modifier"
		for output in g.get_active_outputs():
			if not output.unlocked:
				continue
			if output.discrete:
				return "discrete_production"
			changing[output.resource_id] = true
			if not state.is_resource_discovered(output.resource_id):
				return "discovery_boundary"
	if state.get_heat_leak_per_second() > 0.0:
		changing[ResourceIds.HEAT] = true
	if state.get_matter_decay_per_second() > 0.0:
		changing[ResourceIds.MATTER] = true
		changing[ResourceIds.HEAT] = true
	# Every pending automatic upgrade must have an immutable unmet requirement.
	# Otherwise evaluate exact ticks, including the original ordered application.
	for u in state.upgrades.values():
		if not u.definition.automatic or u.is_maxed():
			continue
		var blocked: bool = false
		for requirement in u.definition.requirements:
			if not state.upgrade_system.requirement_met(requirement):
				if requirement.type != RequirementTypes.RESOURCE or not changing.has(requirement.target_id):
					blocked = true
		if not blocked:
			return "automatic_resource_boundary"
	return ""


# This standalone experiment owns a fresh, scale-one TimeManager context.
# Trials have no clock callbacks; commit the interval clocks with accepted time.
func _sync_clocks() -> void:
	manager.game_time = elapsed
	manager.offline_time = elapsed
	manager.prestige_time = elapsed
	manager.current_offline_duration = elapsed


func _signature() -> String:
	var started: int = Time.get_ticks_usec()
	var result: String = Metrics.discrete(simulation.state, false)
	counters["event_detection_usec"] += Time.get_ticks_usec() - started
	return result


func _advance(delta: float, end: float) -> void:
	simulation.state.set_lava_mite_dormancy_penalty(manager.get_dormancy_penalty(end))
	var started: int = Time.get_ticks_usec()
	simulation.update(delta, true)
	counters["numerical_usec"] += Time.get_ticks_usec() - started
	counters["evaluations"] += 1


func _sample(tick: int) -> void:
	if samples.has(tick):
		return
	var started: int = Time.get_ticks_usec()
	samples[tick] = {"numeric": Metrics.numeric(simulation.state, manager), "discrete": Metrics.discrete(simulation.state),
		"rng": str(simulation.state.gameplay_rng.state)}
	counters["audit_capture_usec"] += Time.get_ticks_usec() - started


func _capture_checkpoint() -> Dictionary:
	var start: int = Time.get_ticks_usec() if profile_checkpoints else 0
	var value: Dictionary = Checkpoint.capture(simulation)
	if profile_checkpoints:
		counters["all_capture_usec"] += Time.get_ticks_usec() - start
		counters["capture_calls"] += 1
	return value


func _restore_checkpoint(value: Dictionary) -> void:
	var start: int = Time.get_ticks_usec() if profile_checkpoints else 0
	Checkpoint.restore(simulation, value)
	if profile_checkpoints:
		counters["all_restore_usec"] += Time.get_ticks_usec() - start
		counters["restore_calls"] += 1


func _completed_interval(_ticks: int, _adaptive: bool) -> void:
	pass


func run(seconds: float) -> Dictionary:
	elapsed = 0.0
	duration = maxf(seconds, 0.0)
	samples.clear()
	attempts.clear()
	counters = {"evaluations": 0, "accepted": 0, "rejected": 0, "fallback_ticks": 0,
		"fallback_reasons": {}, "rejection_reasons": {}, "rejection_fields": {}, "rejected_usec": 0, "event_detection_usec": 0, "trial_usec": 0, "fallback_usec": 0,
		"all_capture_usec": 0, "all_restore_usec": 0, "capture_calls": 0, "restore_calls": 0, "checkpoint_usec": 0, "numerical_usec": 0, "audit_capture_usec": 0, "initial_checkpoint_bytes": 0, "strict_failure": ""}
	var finite_configuration: bool = true
	for value in [seconds, maximum_step, minimum_step, absolute_tolerance, relative_tolerance, event_safety_margin, audit_interval]:
		finite_configuration = finite_configuration and is_finite(value)
	if not finite_configuration or not is_finite(maximum_step) or maximum_step < REFERENCE_STEP or minimum_step < REFERENCE_STEP or absolute_tolerance <= 0.0 or relative_tolerance < 0.0 or event_safety_margin < 0.0:
		counters["strict_failure"] = "Invalid experimental configuration; no simulation was performed."
		return counters
	if manager.time_scale != 1.0 or manager.stabilization_countdown_active or manager.dormancy_recovery_remaining != 0.0 or manager.game_time != 0.0:
		counters["strict_failure"] = "Unsupported TimeManager context; use a fresh scale-one experimental interval."
		return counters
	if duration <= 0.0:
		return counters
	var total_ticks: int = ceili(duration / REFERENCE_STEP)
	var audit_ticks: int = maxi(1, floori(audit_interval / REFERENCE_STEP))
	var max_ticks: int = maxi(1, floori(maximum_step / REFERENCE_STEP))
	var min_ticks: int = maxi(2, ceili(minimum_step / REFERENCE_STEP))
	var proposal: int = min_ticks
	var tick: int = 0
	var retry_ticks: int = 0
	simulation.state.simulation_statistics = manager.simulation_statistics
	simulation.prepare_offline()
	while tick < total_ticks:
		var completed_ticks: int = 0
		var completed_adaptive: bool = false
		var checkpoint_tick: int = mini(total_ticks, (floori(float(tick) / float(audit_ticks)) + 1) * audit_ticks)
		var start: int = Time.get_ticks_usec()
		var reason: String = guard()
		counters["event_detection_usec"] += Time.get_ticks_usec() - start
		var n: int = mini(mini(proposal, max_ticks), checkpoint_tick - tick)
		if reason != "" or n < min_ticks:
			start = Time.get_ticks_usec()
			var count: int = mini(maxi(maxi(1, fallback_window_ticks), retry_ticks), checkpoint_tick - tick)
			if reason == "" and retry_ticks > 0:
				reason = "numerical_retry_cooldown"
			for _index in range(count):
				var delta: float = minf(REFERENCE_STEP, duration - elapsed)
				if delta > 0.0:
					elapsed = minf(duration, elapsed + delta)
					_sync_clocks()
					_advance(delta, elapsed)
				tick += 1
				counters["fallback_ticks"] += 1
			counters["fallback_reasons"][reason if reason != "" else "minimum_step"] = int(counters["fallback_reasons"].get(reason if reason != "" else "minimum_step", 0)) + count
			counters["fallback_usec"] += Time.get_ticks_usec() - start
			proposal = min_ticks
			completed_ticks = count
		else:
			start = Time.get_ticks_usec()
			var attempt_start: int = start
			trial_failure_reason = ""
			var saved: Dictionary = _capture_checkpoint()
			counters["checkpoint_usec"] += Time.get_ticks_usec() - start
			if counters["initial_checkpoint_bytes"] == 0:
				counters["initial_checkpoint_bytes"] = var_to_bytes(saved).size()
			var signature: String = _signature()
			var rng: int = simulation.state.gameplay_rng.state
			var h: float = minf(float(n) * REFERENCE_STEP, duration - elapsed)
			start = Time.get_ticks_usec()
			_advance(h, elapsed + h)
			var coarse: Dictionary = Metrics.numeric(simulation.state)
			if _signature() != signature or simulation.state.gameplay_rng.state != rng:
				counters["strict_failure"] = "Unexpected coarse-trial discrete event; discard this experimental state."
				return counters
			_restore_checkpoint(saved)
			var first: float = float(n >> 1) * REFERENCE_STEP
			_advance(first, elapsed + first)
			_advance(h - first, elapsed + h)
			var fine: Dictionary = Metrics.numeric(simulation.state)
			counters["trial_usec"] += Time.get_ticks_usec() - start
			if _signature() != signature or simulation.state.gameplay_rng.state != rng:
				counters["strict_failure"] = "Unexpected fine-trial discrete event; discard this experimental state."
				return counters
			var error: float = 0.0
			var worst_field: String = ""
			var rejection_reason: String = "numerical_error"
			for key in coarse:
				if not fine.has(key):
					fine[key] = 0.0
			for key in fine:
				var a: float = float(coarse.get(key, 0.0))
				var b: float = float(fine[key])
				var budget: float = absolute_tolerance + relative_tolerance * maxf(absf(a), absf(b))
				if distribute_error_budget and not str(key).ends_with("highest_amount"):
					budget *= h / duration
				var value: float = absf(a - b) / maxf(budget, 1e-30) if is_finite(a) and is_finite(b) else INF
				if value > error:
					error = value
					worst_field = str(key)
			# Reject environmental threshold crossings, leaving the crossing on
			# the authoritative grid. Margin is in resource units, not seconds.
			for pair in [[ResourceIds.HEAT, simulation.state.realm_effects.heat_leak_threshold], [ResourceIds.MATTER, simulation.state.realm_effects.matter_decay_threshold]]:
				var before: float = saved["amounts"][pair[0]] - float(pair[1])
				var after: float = fine["resource/" + pair[0]] - float(pair[1])
				if before * after < 0.0 or (absf(after) < event_safety_margin and before != after):
					error = INF
					rejection_reason = "environmental_threshold"
			if trial_failure_reason != "":
				error = INF
				rejection_reason = trial_failure_reason
			if trace_attempts:
				attempts.append({"tick": tick, "ticks": n, "error": error, "field": worst_field, "reason": rejection_reason if error > 1.0 else "accepted", "usec": Time.get_ticks_usec() - attempt_start})
			if error <= 1.0:
				elapsed = minf(duration, elapsed + h)
				_sync_clocks()
				tick += n
				counters["accepted"] += 1
				retry_ticks = 0
				_sample(tick) # Audit every accepted endpoint, plus fixed checkpoints.
				var next_proposal: int = n * 2
				if preserve_proposal_at_audit and n < proposal:
					next_proposal = maxi(proposal, next_proposal)
				proposal = mini(max_ticks, next_proposal) if error < 0.25 else n
				completed_ticks = n
				completed_adaptive = true
			else:
				_restore_checkpoint(saved)
				counters["rejected"] += 1
				counters["rejected_usec"] += Time.get_ticks_usec() - attempt_start
				counters["rejection_reasons"][rejection_reason] = int(counters["rejection_reasons"].get(rejection_reason, 0)) + 1
				counters["rejection_fields"][worst_field] = int(counters["rejection_fields"].get(worst_field, 0)) + 1
				proposal = n >> 1
				if proposal < min_ticks and numerical_retry_max_ticks > 0:
					retry_ticks = mini(numerical_retry_max_ticks, maxi(fallback_window_ticks, retry_ticks * 2))
		if tick == checkpoint_tick:
			_sample(tick)
		if completed_ticks > 0:
			_completed_interval(completed_ticks, completed_adaptive)
	counters["fallback_fraction"] = float(counters["fallback_ticks"]) / float(total_ticks)
	return counters.duplicate(true)

rejected_proposal_sources.feedback_offline.gd:
extends "res://tests/experimental/adaptive_offline.gd"

# Experimental second-order coarse operator for the *reference map*, not an
# ODE reimplementation. Every slope is measured using Simulation.update(0.1).
# The outer step-doubling controller and all discrete guards remain authoritative.
var map_operator_usec: int = 0
var reuse_probe_fields: bool = false
var ensure_statistics_once: bool = false


func _init(game_simulation: Simulation) -> void:
	super(game_simulation)
	numerical_retry_max_ticks = 1000


func guard() -> String:
	var reason: String = super()
	if reason != "":
		return reason
	# Commit the normal offline-entry/logging transition on reference ticks.
	# Restricted checkpoints must not restore away that one-time housekeeping.
	if not simulation._gameplay_was_offline or simulation.state.track_gameplay_interval_statistics or simulation._gameplay_snapshot_realm_run_index != simulation.state.gameplay_realm_run_index:
		return "offline_entry_transition"
	return ""


func run(seconds: float) -> Dictionary:
	map_operator_usec = 0
	var result: Dictionary = super(seconds)
	counters["map_operator_usec"] = map_operator_usec
	result["map_operator_usec"] = map_operator_usec
	return result


func _advance(delta: float, end: float) -> void:
	if delta <= REFERENCE_STEP + 1e-12:
		super(delta, end)
		return
	var started: int = Time.get_ticks_usec()
	_map_advance(delta, end)
	map_operator_usec += Time.get_ticks_usec() - started


func _map_advance(delta: float, end: float) -> void:
	var saved: Dictionary = _capture_checkpoint()
	var initial: Dictionary = Metrics.numeric(simulation.state)
	super._advance(REFERENCE_STEP, end - delta + REFERENCE_STEP)
	var first: Dictionary = Metrics.numeric(simulation.state)
	var ticks: float = delta / REFERENCE_STEP
	var predicted: Dictionary = {}
	for id in simulation.state.resources:
		var key: String = "resource/" + str(id)
		predicted[id] = float(initial[key]) + ticks * (float(first[key]) - float(initial[key]))
		if not is_finite(predicted[id]) or float(predicted[id]) < 0.0:
			trial_failure_reason = "predictor_resource_exhaustion"
			_restore_checkpoint(saved)
			return
	_restore_checkpoint(saved)
	for id in predicted:
		simulation.state.resources[id].amount = predicted[id]
	var before_probe: Dictionary = initial if reuse_probe_fields else Metrics.numeric(simulation.state)
	super._advance(REFERENCE_STEP, end)
	var endpoint: Dictionary = Metrics.numeric(simulation.state)
	var result: Dictionary = {}
	for key in first:
		var base: float = float(initial.get(key, 0.0))
		var d0: float = float(first[key]) - base
		var before_value: float = float(before_probe.get(key, 0.0))
		if reuse_probe_fields and str(key).begins_with("resource/"):
			before_value = float(predicted[str(key).trim_prefix("resource/")])
		var d1: float = float(endpoint.get(key, 0.0)) - before_value
		# For n=1 this is F_0.1 exactly. For n>1, the (n-1) correction
		# matches the n(n-1)/2 term of repeated discrete-map composition.
		result[key] = base + ticks * d0 + (ticks - 1.0) * 0.5 * (d1 - d0)
	for key in result:
		var value: float = float(result[key])
		if not is_finite(value) or (str(key).begins_with("resource/") and value < 0.0):
			trial_failure_reason = "corrector_resource_exhaustion"
			_restore_checkpoint(saved)
			return
		if (str(key).ends_with("total_produced") or str(key).ends_with("total_consumed") or str(key).ends_with("total_lost") or str(key).ends_with("/overflow") or str(key).ends_with("/decay")) and value < float(initial.get(key, 0.0)):
			trial_failure_reason = "negative_integrated_flow"
			_restore_checkpoint(saved)
			return
	_restore_checkpoint(saved)
	for id in simulation.state.resources:
		simulation.state.resources[id].amount = float(result["resource/" + str(id)])
	var objects: Array = [simulation.state.resource_statistics, simulation.state.current_run_statistics, simulation.state.simulation_statistics]
	var prefixes: Array[String] = ["lifetime", "run", "offline"]
	for index in range(objects.size()):
		var stats: ResourceStatistics = objects[index]
		if stats == null:
			continue
		var prefix: String = prefixes[index]
		stats.total_overflow = float(result[prefix + "/overflow"])
		stats.total_matter_decayed = float(result[prefix + "/decay"])
		for id in simulation.state.resources:
			var path: String = prefix + "/" + str(id) + "/"
			if ensure_statistics_once and (result.has(path + "total_produced") or result.has(path + "total_consumed") or result.has(path + "total_lost") or first.has(path + "highest_amount")):
				stats._ensure_resource(id)
			for field in ["total_produced", "total_consumed", "total_lost"]:
				if result.has(path + field):
					if not ensure_statistics_once:
						stats._ensure_resource(id)
					stats.statistics[id][field] = result[path + field]
			var peak_key: String = path + "highest_amount"
			if not first.has(peak_key):
				continue
			var peak: float = maxf(float(initial.get(peak_key, 0.0)), float(first[peak_key]))
			# Preserve reference microstep peaks, rather than recording the
			# fictitious lump production of a long Simulation.update(delta).
			if float(endpoint.get(peak_key, 0.0)) > float(initial.get(peak_key, 0.0)):
				var resource_key: String = "resource/" + str(id)
				var last_increment: float = float(endpoint[resource_key]) - float(predicted[id] if reuse_probe_fields else before_probe[resource_key])
				peak = maxf(peak, float(endpoint[peak_key]) + float(result[resource_key]) - float(predicted[id]) - last_increment)
			if not ensure_statistics_once:
				stats._ensure_resource(id)
			stats.statistics[id]["highest_amount"] = peak
	simulation.state.total_overflow_this_prestige = float(result["reward/overflow"])
	simulation.state.total_matter_decayed_this_prestige = float(result["reward/decay"])

	simulation.state.set_lava_mite_dormancy_penalty(manager.get_dormancy_penalty(end))

rejected_proposal_sources.accuracy_modes.gd:
extends RefCounted

# Experimental policies only. No player setting or production caller.
const PRESETS: Dictionary = {
	"precise": {"force_exact": true, "relative_tolerance": 0.0, "absolute_tolerance": 1e-8, "maximum_step": 0.1},
	"balanced": {"force_exact": false, "relative_tolerance": 1e-4, "absolute_tolerance": 1e-8, "maximum_step": 60.0},
	"fast": {"force_exact": false, "relative_tolerance": 1e-3, "absolute_tolerance": 1e-8, "maximum_step": 60.0}
}
const COMMON: Dictionary = {"minimum_step": 0.1, "event_safety_margin": 0.1,
	"fallback_window_ticks": 10, "numerical_retry_max_ticks": 1000,
	"distribute_error_budget": true, "audit_interval": 60.0,
	"short_exact_seconds": 600.0, "preserve_proposal_at_audit": true,
	"reuse_probe_fields": false, "ensure_statistics_once": false}

static func configuration(mode: String, overrides: Dictionary = {}) -> Dictionary:
	if not PRESETS.has(mode):
		return {"error": "Unknown experimental accuracy mode: " + mode}
	var result: Dictionary = COMMON.duplicate(true)
	result.merge(PRESETS[mode], true)
	for key in overrides:
		if not result.has(key):
			return {"error": "Unknown experimental configuration key: " + str(key)}
		var supplied: Variant = overrides[key]
		if result[key] is bool:
			if not supplied is bool:
				return {"error": "Expected a boolean configuration value: " + str(key)}
		else:
			if not (supplied is float or supplied is int) or not is_finite(float(supplied)):
				return {"error": "Expected a finite numeric configuration value: " + str(key)}
			if result[key] is int and float(supplied) != floorf(float(supplied)):
				return {"error": "Expected an integer configuration value: " + str(key)}
		result[key] = supplied
	if float(result["minimum_step"]) < TimeManager.OFFLINE_MAX_GAME_STEP or float(result["maximum_step"]) < float(result["minimum_step"]) or float(result["absolute_tolerance"]) <= 0.0 or float(result["relative_tolerance"]) < 0.0 or float(result["event_safety_margin"]) < 0.0 or int(result["fallback_window_ticks"]) < 1 or int(result["numerical_retry_max_ticks"]) < 0 or float(result["audit_interval"]) < TimeManager.OFFLINE_MAX_GAME_STEP or float(result["short_exact_seconds"]) < 0.0:
		return {"error": "Experimental configuration outside supported limits."}
	if mode == "precise" and (not result["force_exact"] or float(result["maximum_step"]) != TimeManager.OFFLINE_MAX_GAME_STEP or float(result["relative_tolerance"]) != 0.0):
		return {"error": "Precise mode cannot approximate the reference simulator."}
	return result


static func prestige_exposed(state: GameState) -> bool:
	# The production reward API does not expose dependency metadata. Use a
	# conservative currency gate instead of guessing distance to a floor boundary
	# or duplicating the reward formula. Even a currently-zero reward is protected.
	if state.get_resource_amount(ResourceIds.CRYSTALLIZED_FLAME) > 0.0:
		return true
	for generator in state.generators.values():
		if not generator.unlocked or generator.level <= 0 or generator.manually_paused:
			continue
		for output in generator.get_active_outputs():
			if output.unlocked and output.resource_id == ResourceIds.CRYSTALLIZED_FLAME:
				return true
	return false

rejected_proposal_sources.horizon_runner.gd:
extends "res://tests/experimental/feedback_offline.gd"

const Modes = preload("res://tests/experimental/accuracy_modes.gd")
var accuracy_mode: String = "balanced"
var overrides: Dictionary = {}
var diagnostics: bool = false
var segment_seconds: float = 3600.0
var audit_all_accepted: bool = true
var segment_callback: Callable
var segments: Array[Dictionary] = []
var effective_configuration: Dictionary = {}
var _policy_reason: String = ""
var _segment_tick: int = 0
var _segment_start_tick: int = 0
var _segment_start_usec: int = 0
var _counter_start: Dictionary = {}
var _widths: Dictionary = {}
var _adaptive_ticks: int = 0


func guard() -> String:
	if force_exact:
		return _policy_reason
	if Modes.prestige_exposed(simulation.state):
		return "prestige_currency_exposure"
	return super()


func run(seconds: float) -> Dictionary:
	effective_configuration = Modes.configuration(accuracy_mode, overrides)
	if effective_configuration.has("error"):
		return {"strict_failure": effective_configuration["error"], "evaluations": 0}
	for key in effective_configuration:
		if key != "short_exact_seconds":
			set(key, effective_configuration[key])
	var short_limit: float = float(effective_configuration["short_exact_seconds"])
	if not is_finite(short_limit) or short_limit < 0.0 or not is_finite(segment_seconds) or segment_seconds <= 0.0:
		return {"strict_failure": "Invalid experimental horizon configuration.", "evaluations": 0}
	_policy_reason = "precise_mode"
	if not force_exact and seconds <= short_limit:
		force_exact = true
		_policy_reason = "short_duration_exact"
	var audit_ticks: int = maxi(1, floori(audit_interval / REFERENCE_STEP))
	var segment_ticks: int = roundi(segment_seconds / REFERENCE_STEP)
	if diagnostics and (segment_ticks < audit_ticks or segment_ticks % audit_ticks != 0):
		return {"strict_failure": "Diagnostic segments must align with existing audit boundaries.", "evaluations": 0}
	segments.clear()
	_counter_start.clear()
	_widths.clear()
	_adaptive_ticks = 0
	_segment_start_tick = 0
	_segment_tick = segment_ticks
	_segment_start_usec = Time.get_ticks_usec()
	profile_checkpoints = diagnostics
	var result: Dictionary = super(seconds)
	if diagnostics and elapsed > float(_segment_start_tick) * REFERENCE_STEP + 1e-8:
		_record_segment(roundi(elapsed / REFERENCE_STEP))
	result["policy"] = _policy_reason if force_exact else accuracy_mode
	result["configuration"] = effective_configuration.duplicate(true)
	return result


func _sample(tick: int) -> void:
	# Optional retained audit density is observational: the timestep controller,
	# its error fields and per-trial discrete/RNG checks are never disabled.
	var audit_ticks: int = maxi(1, floori(audit_interval / REFERENCE_STEP))
	if not audit_all_accepted and tick % audit_ticks != 0 and tick != ceili(duration / REFERENCE_STEP):
		return
	super(tick)
	if samples.has(tick):
		samples[tick]["prestige"] = PrestigeSystem.new().calculate_eternal_flame_gain(simulation.state)


func _completed_interval(ticks: int, adaptive: bool) -> void:
	if not diagnostics:
		return
	if adaptive:
		_adaptive_ticks += ticks
		_widths[ticks] = int(_widths.get(ticks, 0)) + 1
	var now_tick: int = roundi(elapsed / REFERENCE_STEP)
	if now_tick >= _segment_tick:
		_record_segment(now_tick)
		_segment_tick += roundi(segment_seconds / REFERENCE_STEP)


func _record_segment(tick: int) -> void:
	var now: int = Time.get_ticks_usec()
	var snapshot: Dictionary = counters.duplicate(true)
	snapshot["map_operator_usec"] = map_operator_usec
	var delta: Dictionary = {}
	for key in snapshot:
		if snapshot[key] is int:
			delta[key] = int(snapshot[key]) - int(_counter_start.get(key, 0))
		elif snapshot[key] is Dictionary:
			delta[key] = {}
			for reason in snapshot[key]:
				delta[key][reason] = int(snapshot[key][reason]) - int(_counter_start.get(key, {}).get(reason, 0))
	var steps: Array = _widths.keys()
	steps.sort()
	var count: int = 0
	for width in steps:
		count += int(_widths[width])
	var median_ticks: float = 0.0
	if count > 0:
		# Average the two middle ranks, including unequal histogram weights.
		for rank in [(count - 1) >> 1, count >> 1]:
			var cumulative: int = 0
			for width in steps:
				cumulative += int(_widths[width])
				if cumulative > rank:
					median_ticks += float(width) * 0.5
					break
	var state: GameState = simulation.state
	var active: Array[String] = []
	var modifiers: Dictionary = {}
	for generator in state.generators.values():
		if not generator.unlocked or (not generator.operating and not generator.cycle_active):
			continue
		active.append(generator.definition.id)
		var values: Array = []
		for modifier in generator.modifiers:
			values.append({"id": modifier.id, "resource": modifier.dynamic_resource_id,
				"formula": modifier.dynamic_formula, "effective": modifier.get_effective_multiplier(state, generator)})
		modifiers[generator.definition.id] = values
	var automation_count: int = 0
	for automation in [state.generator_automation_manager, state.upgrade_automation_manager]:
		for entry in automation.automation_states.values():
			if entry["enabled"]:
				automation_count += 1
	var wall: float = float(now - _segment_start_usec) / 1e6
	var simulated_seconds: float = minf(duration, float(tick) * REFERENCE_STEP) - minf(duration, float(_segment_start_tick) * REFERENCE_STEP)
	var record: Dictionary = {"from": float(_segment_start_tick) * REFERENCE_STEP,
		"until": minf(duration, float(tick) * REFERENCE_STEP), "wall_seconds": wall,
		"throughput_simulated_seconds_per_second": simulated_seconds / maxf(wall, 1e-9),
		"counters": delta, "adaptive_coverage": minf(1.0, float(_adaptive_ticks) * REFERENCE_STEP / maxf(simulated_seconds, 1e-30)),
		"average_step": float(_adaptive_ticks) * REFERENCE_STEP / maxi(count, 1),
		"median_step": median_ticks * REFERENCE_STEP,
		"maximum_step": float(steps[-1]) * REFERENCE_STEP if not steps.is_empty() else 0.0,
		"rejected_effort_fraction": float(delta.get("rejected_usec", 0)) / maxf(wall * 1e6, 1.0),
		"numeric": Metrics.numeric(state, manager), "active_generators": active,
		"enabled_automation_count": automation_count, "modifiers": modifiers,
		"thresholds": {"heat": state.realm_effects.heat_leak_threshold,
			"matter": state.realm_effects.matter_decay_threshold, "ash": state.get_resource_threshold(ResourceIds.ASH)},
		"retained_samples": samples.size()}
	segments.append(record)
	if segment_callback.is_valid():
		segment_callback.call(record)
	_counter_start = snapshot
	_widths.clear()
	_adaptive_ticks = 0
	_segment_start_tick = tick
	_segment_start_usec = Time.get_ticks_usec()

rejected_proposal_sources.horizon_benchmark.gd:
extends SceneTree

const Runner = preload("res://tests/experimental/horizon_runner.gd")
const Fixtures = preload("res://tests/experimental/horizon_fixtures.gd")
const Metrics = preload("res://tests/experimental/adaptive_metrics.gd")
const Observer = preload("res://tests/experimental/adaptive_tests.gd")

func _initialize() -> void:
	call_deferred("_run")


func _options() -> Dictionary:
	var result: Dictionary = {"scenario": "feedback", "duration": "600", "accuracy": "balanced",
		"action": "paired", "variant": "normal", "diagnostics": "false", "audit": "dense", "candidate": "default"}
	for argument in OS.get_cmdline_user_args():
		var pair: PackedStringArray = argument.trim_prefix("--").split("=", true, 1)
		if pair.size() == 2:
			result[pair[0]] = pair[1]
	return result


static func header(options: Dictionary, state: GameState) -> Dictionary:
	var sources: Dictionary = {}
	for path in ["simulation/simulation.gd", "Game/time_manager.gd", "game_state.gd", "Generators/generator.gd",
		"Game/modifier.gd", "Game/modifiersensitivity.gd", "Game/resource_statistics.gd", "Game/prestige_system.gd",
		"Game/gameplay_random.gd", "Game/save_manager.gd", "Upgrades/UpgradeRegistry.gd",
		"tests/experimental/adaptive_benchmark.gd", "tests/experimental/horizon_fixtures.gd", "tests/experimental/adaptive_tests.gd"]:
		if FileAccess.file_exists("res://" + path):
			sources[path] = FileAccess.get_file_as_string("res://" + path).sha256_text()
	return {"schema": 1, "engine": Engine.get_version_info()["string"], "sources": sources,
		"duration": float(options["duration"]), "scenario": options["scenario"], "variant": options["variant"],
		"initial": (Metrics.discrete(state) + JSON.stringify(Metrics.numeric(state)) + str(state.gameplay_rng.state)).sha256_text()}


static func sample(state: GameState, manager: TimeManager) -> Dictionary:
	return {"numeric": Metrics.numeric(state, manager), "discrete": Metrics.discrete(state),
		"rng": str(state.gameplay_rng.state), "prestige": PrestigeSystem.new().calculate_eternal_flame_gain(state)}


static func store_cache(path: String, data: Dictionary) -> void:
	if path == "":
		return
	var file := FileAccess.open(path + ".partial", FileAccess.WRITE)
	assert(file != null, "Cannot write reference trace.")
	file.store_var(data)
	file.close()
	assert(DirAccess.rename_absolute(path + ".partial", path) == OK, "Cannot commit reference trace.")


func _reference(options: Dictionary, wanted: Dictionary = {}) -> Dictionary:
	var state: GameState = Fixtures.make_state(options["scenario"], options["variant"])
	var identity: Dictionary = header(options, state)
	var cache_path: String = options.get("cache", "")
	if FileAccess.file_exists(cache_path) and options.get("refresh_reference", "false") != "true":
		var file := FileAccess.open(cache_path, FileAccess.READ)
		var cached: Variant = file.get_var(false)
		if not cached is Dictionary or cached.get("header", {}) != identity:
			return {"error": "Reference cache does not match sources/engine/fixture/duration."}
		var covers_requested: bool = true
		for tick in wanted:
			covers_requested = covers_requested and cached["samples"].has(tick)
		if covers_requested and cached.get("complete", false):
			cached["reused"] = true
			return cached
		# Recompute the oracle if a denser audit is requested, keeping the
		# union of previously captured times. This is not save-state resumption.
		wanted = wanted.duplicate()
		for tick in cached["samples"]:
			wanted[tick] = true
	var simulation := Simulation.new(state)
	Observer.new().observe(simulation)
	var manager := TimeManager.new(simulation)
	state.simulation_statistics = manager.simulation_statistics
	var seconds: float = float(options["duration"])
	var data: Dictionary = {"header": identity, "samples": {}, "segments": [], "complete": false, "evaluations": 0}
	var start: int = Time.get_ticks_usec()
	var segment_start: int = start
	var audit_usec: int = 0
	var io_usec: int = 0
	var segment_audit: int = 0
	var elapsed: float = 0.0
	for tick in range(ceili(seconds / 0.1)):
		var delta: float = minf(0.1, seconds - elapsed)
		elapsed = minf(seconds, elapsed + delta)
		manager.game_time += delta
		manager.offline_time += delta
		manager.prestige_time += delta
		manager.current_offline_duration += delta
		state.set_lava_mite_dormancy_penalty(manager.get_dormancy_penalty(elapsed))
		simulation.update(delta, true)
		data["evaluations"] += 1
		if (tick + 1) % 600 == 0 or wanted.has(tick + 1) or tick + 1 == ceili(seconds / 0.1):
			var before: int = Time.get_ticks_usec()
			data["samples"][tick + 1] = sample(state, manager)
			audit_usec += Time.get_ticks_usec() - before
		if (tick + 1) % 36000 == 0 or tick + 1 == ceili(seconds / 0.1):
			var now: int = Time.get_ticks_usec()
			data["segments"].append({"until": elapsed, "wall_seconds": float(now - segment_start) / 1e6,
				"compute_seconds": float(now - segment_start - (audit_usec - segment_audit)) / 1e6,
				"numeric": Metrics.numeric(state, manager)})
			data["covered_seconds"] = elapsed
			data["compute_seconds"] = float(now - start - audit_usec - io_usec) / 1e6
			var before_io: int = Time.get_ticks_usec()
			print("REFERENCE_SEGMENT " + JSON.stringify(data["segments"][-1]))
			store_cache(cache_path, data)
			io_usec += Time.get_ticks_usec() - before_io
			segment_start = Time.get_ticks_usec()
			segment_audit = audit_usec
	data["compute_seconds"] = float(Time.get_ticks_usec() - start - audit_usec - io_usec) / 1e6
	data["wall_seconds"] = float(Time.get_ticks_usec() - start) / 1e6
	data["audit_usec"] = audit_usec
	data["cache_io_usec"] = io_usec
	data["complete"] = true
	data["final"] = sample(state, manager)
	store_cache(cache_path, data)
	return data


func _run() -> void:
	var options: Dictionary = _options()
	if options["action"] == "reference":
		var reference: Dictionary = _reference(options)
		if reference.has("error"):
			print("HORIZON_JSON " + JSON.stringify({"phase": "reference", "complete": false, "error": reference["error"]}))
			quit(1)
			return
		print("HORIZON_JSON " + JSON.stringify({"phase": "reference", "complete": reference["complete"],
			"seconds": reference["compute_seconds"], "evaluations": reference["evaluations"]}))
		quit()
		return
	var state: GameState = Fixtures.make_state(options["scenario"], options["variant"])
	var initial: Dictionary = header(options, state)
	var runner = Runner.new(Simulation.new(state))
	Observer.new().observe(runner.simulation)
	runner.accuracy_mode = options["accuracy"]
	runner.audit_all_accepted = options["audit"] == "dense"
	runner.diagnostics = options["diagnostics"] == "true"
	runner.segment_seconds = float(options.get("segment", "3600"))
	runner.segment_callback = func(record: Dictionary) -> void: print("ADAPTIVE_SEGMENT " + JSON.stringify(record))
	var candidates: Dictionary = {
		"baseline": {"preserve_proposal_at_audit": false, "reuse_probe_fields": false, "ensure_statistics_once": false},
		"proposal": {"preserve_proposal_at_audit": true, "reuse_probe_fields": false, "ensure_statistics_once": false},
		"fields": {"preserve_proposal_at_audit": false, "reuse_probe_fields": true, "ensure_statistics_once": false},
		"ensure": {"preserve_proposal_at_audit": false, "reuse_probe_fields": false, "ensure_statistics_once": true},
		"combined": {"preserve_proposal_at_audit": true, "reuse_probe_fields": true, "ensure_statistics_once": true}}
	if candidates.has(options["candidate"]):
		runner.overrides = candidates[options["candidate"]].duplicate(true)
	if options.has("short_exact"):
		runner.overrides["short_exact_seconds"] = float(options["short_exact"])
	var before: int = Time.get_ticks_usec()
	var counters: Dictionary = runner.run(float(options["duration"]))
	var wall: float = float(Time.get_ticks_usec() - before) / 1e6
	var final: Dictionary = sample(state, runner.manager)
	var result: Dictionary = {"phase": "adaptive", "options": options, "initial": initial,
		"seconds": wall, "counters": counters, "segments": runner.segments,
		"final": final, "complete": counters.get("strict_failure", "") == "", "samples": runner.samples.size(),
		"sources": {"runner": FileAccess.get_file_as_string("res://tests/experimental/horizon_runner.gd").sha256_text(),
			"modes": FileAccess.get_file_as_string("res://tests/experimental/accuracy_modes.gd").sha256_text(),
			"base": FileAccess.get_file_as_string("res://tests/experimental/adaptive_offline.gd").sha256_text(),
			"feedback": FileAccess.get_file_as_string("res://tests/experimental/feedback_offline.gd").sha256_text()}}
	print("ADAPTIVE_COMPLETE " + JSON.stringify({"seconds": wall, "counters": counters}))
	if not result["complete"]:
		print("HORIZON_JSON " + JSON.stringify(result))
		quit(1)
		return
	if options["action"] != "adaptive":
		var reference: Dictionary = _reference(options, runner.samples if runner.audit_all_accepted else {})
		if reference.has("error") or reference.get("header", {}) != initial:
			result["complete"] = false
			result["error"] = reference.get("error", "Adaptive/reference initial states differ.")
			print("HORIZON_JSON " + JSON.stringify(result))
			quit(1)
			return
		result["reference_complete"] = reference["complete"]
		result["reference_reused"] = reference.get("reused", false)
		result["reference_seconds"] = reference["compute_seconds"]
		result["speedup"] = float(reference["compute_seconds"]) / maxf(wall, 1e-9)
		result["maximum_deviation"] = {"resource_abs": 0.0, "resource_rel": 0.0,
			"statistics_abs": 0.0, "statistics_rel": 0.0, "normalized": 0.0}
		result["discrete_parity"] = true
		result["rng_parity"] = true
		result["prestige_parity"] = true
		var audits: int = 0
		for tick in runner.samples:
			if not reference["samples"].has(tick):
				continue
			var actual: Dictionary = runner.samples[tick]
			var expected: Dictionary = reference["samples"][tick]
			var error: Dictionary = Metrics.compare(expected["numeric"], actual["numeric"], runner.absolute_tolerance, runner.relative_tolerance)
			for key in result["maximum_deviation"]:
				result["maximum_deviation"][key] = maxf(float(result["maximum_deviation"][key]), float(error[key]))
			result["discrete_parity"] = result["discrete_parity"] and actual["discrete"] == expected["discrete"]
			result["rng_parity"] = result["rng_parity"] and actual["rng"] == expected["rng"]
			# The reference reward is included in the discrete fingerprint too.
			result["prestige_parity"] = result["prestige_parity"] and actual["prestige"] == expected["prestige"]
			audits += 1
		result["audits"] = audits
		result["comparison_coverage_seconds"] = reference.get("covered_seconds", 0.0)
		if reference["complete"]:
			result["final_deviation"] = Metrics.compare(reference["final"]["numeric"], final["numeric"], runner.absolute_tolerance, runner.relative_tolerance)
			result["discrete_parity"] = result["discrete_parity"] and reference["final"]["discrete"] == final["discrete"]
			result["rng_parity"] = result["rng_parity"] and reference["final"]["rng"] == final["rng"]
			result["prestige_parity"] = result["prestige_parity"] and reference["final"]["prestige"] == final["prestige"]
			result["exact_numeric_parity"] = var_to_bytes(reference["final"]["numeric"]) == var_to_bytes(final["numeric"])
			result["accuracy_pass"] = float(result["maximum_deviation"]["normalized"]) <= 1.0 and float(result["final_deviation"]["normalized"]) <= 1.0
		else:
			result["accuracy_pass"] = false # An incomplete oracle never counts as a pass.
	print("HORIZON_JSON " + JSON.stringify(result))
	quit()

rejected_proposal_sources.horizon_tests.gd:
extends "res://tests/experimental/adaptive_tests.gd"

const Runner = preload("res://tests/experimental/horizon_runner.gd")
const Modes = preload("res://tests/experimental/accuracy_modes.gd")
const Fixtures = preload("res://tests/experimental/horizon_fixtures.gd")

func run_mode(scenario: String, mode: String, seconds: float, options: Dictionary = {}, dense: bool = true):
	var state: GameState = Fixtures.make_state(scenario)
	var runner = Runner.new(Simulation.new(state))
	observe(runner.simulation)
	runner.accuracy_mode = mode
	runner.overrides = options
	runner.audit_all_accepted = dense
	var result: Dictionary = runner.run(seconds)
	check(result.get("strict_failure", "") == "", "Experimental mode failed: " + str(result))
	return runner


func test_modes() -> void:
	check(Modes.configuration("unknown").has("error"), "Unknown mode was accepted.")
	for options in [{"relative_tolerance": NAN}, {"minimum_step": 0.01}, {"numerical_retry_max_ticks": -1},
		{"fallback_window_ticks": 0}, {"force_exact": "false"}, {"new_parameter": 1}]:
		check(Modes.configuration("balanced", options).has("error"), "Invalid mode configuration was accepted.")
	check(Modes.configuration("precise", {"force_exact": false}).has("error"), "Precise mode could approximate.")
	for scenario in ["feedback", "cycles"]:
		var reference = run_mode(scenario, "precise", 15.0)
		for mode in ["balanced", "fast"]:
			var runner = run_mode(scenario, mode, 15.0)
			check(full(reference.simulation.state) == full(runner.simulation.state), "Short duration mitigation was not binary exact.")
			check(runner.counters["accepted"] == 0 and runner.counters["fallback_ticks"] == 150, "Short duration did not select exact simulation.")
			check(runner.counters.get("fallback_reasons", {}).has("short_duration_exact"), "Short duration decision was not reported.")
	for seconds in [0.0, 0.01, 0.15]:
		var reference = run_mode("stable", "precise", seconds)
		var runner = run_mode("stable", "balanced", seconds)
		check(full(reference.simulation.state) == full(runner.simulation.state), "Zero/fractional interval changed state.")


func test_exact_cleanups() -> void:
	var options: Dictionary = {"short_exact_seconds": 0.0, "preserve_proposal_at_audit": false}
	var baseline = run_mode("feedback", "balanced", 60.0, options)
	for candidate in [{"reuse_probe_fields": true}, {"ensure_statistics_once": true}, {"reuse_probe_fields": true, "ensure_statistics_once": true}]:
		var settings: Dictionary = options.duplicate(true)
		settings.merge(candidate, true)
		var actual = run_mode("feedback", "balanced", 60.0, settings)
		check(var_to_bytes(baseline.samples) == var_to_bytes(actual.samples), "A static cleanup changed a sampled numeric/discrete/RNG state.")
		check(full(baseline.simulation.state) == full(actual.simulation.state), "A static cleanup changed final binary state.")
		check(baseline.counters["evaluations"] == actual.counters["evaluations"], "Cleanup changed controller decisions.")


func test_proposal() -> void:
	var before = run_mode("stable", "balanced", 600.0, {"short_exact_seconds": 0.0, "preserve_proposal_at_audit": false})
	var after = run_mode("stable", "balanced", 600.0, {"short_exact_seconds": 0.0, "preserve_proposal_at_audit": true})
	var reference = run_mode("stable", "precise", 600.0)
	check(after.counters["accepted"] < before.counters["accepted"], "Audit clipping continued to shrink the following proposal.")
	check(Metrics.discrete(after.simulation.state) == Metrics.discrete(reference.simulation.state), "Proposal selection changed a discrete result.")
	check(float(Metrics.compare(Metrics.numeric(reference.simulation.state), Metrics.numeric(after.simulation.state), 1e-8, 1e-4)["normalized"]) <= 1.0, "Proposal selection exceeded the target.")
	check(after.simulation.state.gameplay_rng.state == reference.simulation.state.gameplay_rng.state, "Proposal selection changed RNG state.")


func test_diagnostics() -> void:
	var plain = run_mode("feedback", "balanced", 120.0, {"short_exact_seconds": 0.0}, true)
	var state: GameState = Fixtures.make_state("feedback")
	var instrumented = Runner.new(Simulation.new(state))
	observe(instrumented.simulation)
	instrumented.overrides = {"short_exact_seconds": 0.0}
	instrumented.diagnostics = true
	instrumented.segment_seconds = 60.0
	instrumented.audit_all_accepted = false
	instrumented.run(120.0)
	check(full(plain.simulation.state) == full(state), "Diagnostics/retained-audit policy changed numerical behavior.")
	check(instrumented.segments.size() == 2, "Hourly/minute diagnostic segments were not emitted.")
	var accepted: int = 0
	var fallback: int = 0
	for segment in instrumented.segments:
		accepted += int(segment["counters"]["accepted"])
		fallback += int(segment["counters"]["fallback_ticks"])
		check(float(segment["adaptive_coverage"]) >= 0.0 and float(segment["adaptive_coverage"]) <= 1.0, "Invalid adaptive coverage.")
		check(segment["counters"]["all_restore_usec"] > 0, "State restoration was not profiled.")
	check(accepted == instrumented.counters["accepted"] and fallback == instrumented.counters["fallback_ticks"], "Segment deltas did not sum to global counts.")


func test_prestige_protection() -> void:
	var state: GameState = Fixtures.make_state("reward_boundary")
	var system := PrestigeSystem.new()
	var initial: float = system.calculate_eternal_flame_gain(state)
	var saved_overflow: float = state.total_overflow_this_prestige
	state.total_overflow_this_prestige += 4.0
	check(system.calculate_eternal_flame_gain(state) > initial, "Boundary fixture did not demonstrate integer sensitivity to a tiny relative flow difference.")
	state.total_overflow_this_prestige = saved_overflow
	var reference = run_mode("reward_boundary", "precise", 5.0)
	for mode in ["balanced", "fast"]:
		var actual = run_mode("reward_boundary", mode, 5.0, {"short_exact_seconds": 0.0})
		check(full(reference.simulation.state) == full(actual.simulation.state), "A mode changed resources/statistics at a prestige boundary.")
		check(system.calculate_eternal_flame_gain(actual.simulation.state) > initial, "Reward transition was not exercised.")
		check(actual.counters["accepted"] == 0 and actual.counters["fallback_reasons"].has("prestige_currency_exposure"), "Prestige exposure was approximated.")


func test_fallbacks() -> void:
	for scenario in ["mixed", "automation", "consumers"]:
		var reference = run_mode(scenario, "precise", 30.0)
		for mode in ["balanced", "fast"]:
			var actual = run_mode(scenario, mode, 30.0, {"short_exact_seconds": 0.0})
			check(full(reference.simulation.state) == full(actual.simulation.state), "Mixed/automation/consumer fallback changed binary state.")
			check(actual.counters["accepted"] == 0, "An unsupported discrete controller entered projection.")

head_diagnostic_sources.base:
extends RefCounted

# ISOLATED EXPERIMENT. Nothing in production preloads or calls this class.
# Step doubling estimates the error of the existing ordered update map. It is
# not a proof of accuracy relative to repeated 0.1 s updates: audit that separately.
const Metrics = preload("res://tests/experimental/adaptive_metrics.gd")
const Checkpoint = preload("res://tests/experimental/continuous_checkpoint.gd")
const REFERENCE_STEP: float = TimeManager.OFFLINE_MAX_GAME_STEP

var maximum_step: float = 60.0
var minimum_step: float = REFERENCE_STEP
var absolute_tolerance: float = 1e-8
var relative_tolerance: float = 1e-4
var event_safety_margin: float = 0.1
var fallback_window_ticks: int = 10
var audit_interval: float = 60.0
var distribute_error_budget: bool = true
var force_exact: bool = false
var allow_environmental_feedback: bool = true
# Diagnostics are optional: per-attempt traces are excluded from throughput runs.
var numerical_retry_max_ticks: int = 0
var trial_failure_reason: String = ""
var trace_attempts: bool = false
var attempts: Array[Dictionary] = []

var counters: Dictionary = {}
var samples: Dictionary = {}
var simulation: Simulation
var manager: TimeManager
var elapsed: float = 0.0
var duration: float = 0.0

func _init(game_simulation: Simulation) -> void:
	simulation = game_simulation
	manager = TimeManager.new(simulation)


# There are no generator-specific shortcuts. Consumers, discrete production,
# stateful/dormancy modifiers and discrete controllers deliberately fall back.
func guard() -> String:
	var state: GameState = simulation.state
	if force_exact:
		return "forced_exact"
	if not allow_environmental_feedback and (state.get_heat_leak_per_second() > 0.0 or state.get_matter_decay_per_second() > 0.0):
		return "environmental_feedback"
	if simulation.profiling_enabled or simulation.diagnostics_enabled:
		return "instrumented_simulation"
	if state.prestige_planning:
		return "prestige_planning"
	for automation in [state.generator_automation_manager, state.upgrade_automation_manager]:
		for entry in automation.automation_states.values():
			if entry["enabled"]:
				return "enabled_automation"
	var changing: Dictionary = {}
	for g in state.generators.values():
		if g.cycle_active or g.auto_run_cycles:
			return "cycle_or_auto_run"
		if g.definition.cycle_based:
			continue
		if not g.unlocked:
			continue
		# Throttle flags can change even for paused/level-zero consumers.
		if not g.get_active_inputs().is_empty():
			return "resource_consumers"
		if g.manually_paused and g.operating:
			return "pause_transition"
		if g.manually_paused or g.level <= 0:
			continue
		if not g.operating or g.is_throttled:
			return "operating_transition"
		for modifier in g.modifiers:
			if modifier.dynamic and modifier.dynamic_formula == Modifier.DYNAMIC_LAVA_MITE_DORMANCY:
				return "time_dependent_modifier"
		for output in g.get_active_outputs():
			if not output.unlocked:
				continue
			if output.discrete:
				return "discrete_production"
			changing[output.resource_id] = true
			if not state.is_resource_discovered(output.resource_id):
				return "discovery_boundary"
	if state.get_heat_leak_per_second() > 0.0:
		changing[ResourceIds.HEAT] = true
	if state.get_matter_decay_per_second() > 0.0:
		changing[ResourceIds.MATTER] = true
		changing[ResourceIds.HEAT] = true
	# Every pending automatic upgrade must have an immutable unmet requirement.
	# Otherwise evaluate exact ticks, including the original ordered application.
	for u in state.upgrades.values():
		if not u.definition.automatic or u.is_maxed():
			continue
		var blocked: bool = false
		for requirement in u.definition.requirements:
			if not state.upgrade_system.requirement_met(requirement):
				if requirement.type != RequirementTypes.RESOURCE or not changing.has(requirement.target_id):
					blocked = true
		if not blocked:
			return "automatic_resource_boundary"
	return ""


# This standalone experiment owns a fresh, scale-one TimeManager context.
# Trials have no clock callbacks; commit the interval clocks with accepted time.
func _sync_clocks() -> void:
	manager.game_time = elapsed
	manager.offline_time = elapsed
	manager.prestige_time = elapsed
	manager.current_offline_duration = elapsed


func _signature() -> String:
	var started: int = Time.get_ticks_usec()
	var result: String = Metrics.discrete(simulation.state, false)
	counters["event_detection_usec"] += Time.get_ticks_usec() - started
	return result


func _advance(delta: float, end: float) -> void:
	simulation.state.set_lava_mite_dormancy_penalty(manager.get_dormancy_penalty(end))
	var started: int = Time.get_ticks_usec()
	simulation.update(delta, true)
	counters["numerical_usec"] += Time.get_ticks_usec() - started
	counters["evaluations"] += 1


func _sample(tick: int) -> void:
	if samples.has(tick):
		return
	var started: int = Time.get_ticks_usec()
	samples[tick] = {"numeric": Metrics.numeric(simulation.state, manager), "discrete": Metrics.discrete(simulation.state),
		"rng": str(simulation.state.gameplay_rng.state)}
	counters["audit_capture_usec"] += Time.get_ticks_usec() - started


func run(seconds: float) -> Dictionary:
	elapsed = 0.0
	duration = maxf(seconds, 0.0)
	samples.clear()
	attempts.clear()
	counters = {"evaluations": 0, "accepted": 0, "rejected": 0, "fallback_ticks": 0,
		"fallback_reasons": {}, "rejection_reasons": {}, "rejection_fields": {}, "rejected_usec": 0, "event_detection_usec": 0, "trial_usec": 0, "fallback_usec": 0,
		"checkpoint_usec": 0, "numerical_usec": 0, "audit_capture_usec": 0, "initial_checkpoint_bytes": 0, "strict_failure": ""}
	var finite_configuration: bool = true
	for value in [seconds, maximum_step, minimum_step, absolute_tolerance, relative_tolerance, event_safety_margin, audit_interval]:
		finite_configuration = finite_configuration and is_finite(value)
	if not finite_configuration or not is_finite(maximum_step) or maximum_step < REFERENCE_STEP or minimum_step < REFERENCE_STEP or absolute_tolerance <= 0.0 or relative_tolerance < 0.0 or event_safety_margin < 0.0:
		counters["strict_failure"] = "Invalid experimental configuration; no simulation was performed."
		return counters
	if manager.time_scale != 1.0 or manager.stabilization_countdown_active or manager.dormancy_recovery_remaining != 0.0 or manager.game_time != 0.0:
		counters["strict_failure"] = "Unsupported TimeManager context; use a fresh scale-one experimental interval."
		return counters
	if duration <= 0.0:
		return counters
	var total_ticks: int = ceili(duration / REFERENCE_STEP)
	var audit_ticks: int = maxi(1, floori(audit_interval / REFERENCE_STEP))
	var max_ticks: int = maxi(1, floori(maximum_step / REFERENCE_STEP))
	var min_ticks: int = maxi(2, ceili(minimum_step / REFERENCE_STEP))
	var proposal: int = min_ticks
	var tick: int = 0
	var retry_ticks: int = 0
	simulation.state.simulation_statistics = manager.simulation_statistics
	simulation.prepare_offline()
	while tick < total_ticks:
		var checkpoint_tick: int = mini(total_ticks, (floori(float(tick) / float(audit_ticks)) + 1) * audit_ticks)
		var start: int = Time.get_ticks_usec()
		var reason: String = guard()
		counters["event_detection_usec"] += Time.get_ticks_usec() - start
		var n: int = mini(mini(proposal, max_ticks), checkpoint_tick - tick)
		if reason != "" or n < min_ticks:
			start = Time.get_ticks_usec()
			var count: int = mini(maxi(maxi(1, fallback_window_ticks), retry_ticks), checkpoint_tick - tick)
			if reason == "" and retry_ticks > 0:
				reason = "numerical_retry_cooldown"
			for _index in range(count):
				var delta: float = minf(REFERENCE_STEP, duration - elapsed)
				if delta > 0.0:
					elapsed = minf(duration, elapsed + delta)
					_sync_clocks()
					_advance(delta, elapsed)
				tick += 1
				counters["fallback_ticks"] += 1
			counters["fallback_reasons"][reason if reason != "" else "minimum_step"] = int(counters["fallback_reasons"].get(reason if reason != "" else "minimum_step", 0)) + count
			counters["fallback_usec"] += Time.get_ticks_usec() - start
			proposal = min_ticks
		else:
			start = Time.get_ticks_usec()
			var attempt_start: int = start
			trial_failure_reason = ""
			var saved: Dictionary = Checkpoint.capture(simulation)
			counters["checkpoint_usec"] += Time.get_ticks_usec() - start
			if counters["initial_checkpoint_bytes"] == 0:
				counters["initial_checkpoint_bytes"] = var_to_bytes(saved).size()
			var signature: String = _signature()
			var rng: int = simulation.state.gameplay_rng.state
			var h: float = minf(float(n) * REFERENCE_STEP, duration - elapsed)
			start = Time.get_ticks_usec()
			_advance(h, elapsed + h)
			var coarse: Dictionary = Metrics.numeric(simulation.state)
			if _signature() != signature or simulation.state.gameplay_rng.state != rng:
				counters["strict_failure"] = "Unexpected coarse-trial discrete event; discard this experimental state."
				return counters
			Checkpoint.restore(simulation, saved)
			var first: float = float(n >> 1) * REFERENCE_STEP
			_advance(first, elapsed + first)
			_advance(h - first, elapsed + h)
			var fine: Dictionary = Metrics.numeric(simulation.state)
			counters["trial_usec"] += Time.get_ticks_usec() - start
			if _signature() != signature or simulation.state.gameplay_rng.state != rng:
				counters["strict_failure"] = "Unexpected fine-trial discrete event; discard this experimental state."
				return counters
			var error: float = 0.0
			var worst_field: String = ""
			var rejection_reason: String = "numerical_error"
			for key in coarse:
				if not fine.has(key):
					fine[key] = 0.0
			for key in fine:
				var a: float = float(coarse.get(key, 0.0))
				var b: float = float(fine[key])
				var budget: float = absolute_tolerance + relative_tolerance * maxf(absf(a), absf(b))
				if distribute_error_budget and not str(key).ends_with("highest_amount"):
					budget *= h / duration
				var value: float = absf(a - b) / maxf(budget, 1e-30) if is_finite(a) and is_finite(b) else INF
				if value > error:
					error = value
					worst_field = str(key)
			# Reject environmental threshold crossings, leaving the crossing on
			# the authoritative grid. Margin is in resource units, not seconds.
			for pair in [[ResourceIds.HEAT, simulation.state.realm_effects.heat_leak_threshold], [ResourceIds.MATTER, simulation.state.realm_effects.matter_decay_threshold]]:
				var before: float = saved["amounts"][pair[0]] - float(pair[1])
				var after: float = fine["resource/" + pair[0]] - float(pair[1])
				if before * after < 0.0 or (absf(after) < event_safety_margin and before != after):
					error = INF
					rejection_reason = "environmental_threshold"
			if trial_failure_reason != "":
				error = INF
				rejection_reason = trial_failure_reason
			if trace_attempts:
				attempts.append({"tick": tick, "ticks": n, "error": error, "field": worst_field, "reason": rejection_reason if error > 1.0 else "accepted", "usec": Time.get_ticks_usec() - attempt_start})
			if error <= 1.0:
				elapsed = minf(duration, elapsed + h)
				_sync_clocks()
				tick += n
				counters["accepted"] += 1
				retry_ticks = 0
				_sample(tick) # Audit every accepted endpoint, plus fixed checkpoints.
				proposal = mini(max_ticks, n * 2) if error < 0.25 else n
			else:
				Checkpoint.restore(simulation, saved)
				counters["rejected"] += 1
				counters["rejected_usec"] += Time.get_ticks_usec() - attempt_start
				counters["rejection_reasons"][rejection_reason] = int(counters["rejection_reasons"].get(rejection_reason, 0)) + 1
				counters["rejection_fields"][worst_field] = int(counters["rejection_fields"].get(worst_field, 0)) + 1
				proposal = n >> 1
				if proposal < min_ticks and numerical_retry_max_ticks > 0:
					retry_ticks = mini(numerical_retry_max_ticks, maxi(fallback_window_ticks, retry_ticks * 2))
		if tick == checkpoint_tick:
			_sample(tick)
	counters["fallback_fraction"] = float(counters["fallback_ticks"]) / float(total_ticks)
	return counters.duplicate(true)

head_diagnostic_sources.feedback:
extends "res://tests/experimental/head_adaptive.gd"

# Experimental second-order coarse operator for the *reference map*, not an
# ODE reimplementation. Every slope is measured using Simulation.update(0.1).
# The outer step-doubling controller and all discrete guards remain authoritative.
var map_operator_usec: int = 0


func _init(game_simulation: Simulation) -> void:
	super(game_simulation)
	numerical_retry_max_ticks = 1000


func guard() -> String:
	var reason: String = super()
	if reason != "":
		return reason
	# Commit the normal offline-entry/logging transition on reference ticks.
	# Restricted checkpoints must not restore away that one-time housekeeping.
	if not simulation._gameplay_was_offline or simulation.state.track_gameplay_interval_statistics or simulation._gameplay_snapshot_realm_run_index != simulation.state.gameplay_realm_run_index:
		return "offline_entry_transition"
	return ""


func run(seconds: float) -> Dictionary:
	map_operator_usec = 0
	var result: Dictionary = super(seconds)
	counters["map_operator_usec"] = map_operator_usec
	result["map_operator_usec"] = map_operator_usec
	return result


func _advance(delta: float, end: float) -> void:
	if delta <= REFERENCE_STEP + 1e-12:
		super(delta, end)
		return
	var started: int = Time.get_ticks_usec()
	_map_advance(delta, end)
	map_operator_usec += Time.get_ticks_usec() - started


func _map_advance(delta: float, end: float) -> void:
	var saved: Dictionary = Checkpoint.capture(simulation)
	var initial: Dictionary = Metrics.numeric(simulation.state)
	super._advance(REFERENCE_STEP, end - delta + REFERENCE_STEP)
	var first: Dictionary = Metrics.numeric(simulation.state)
	var ticks: float = delta / REFERENCE_STEP
	var predicted: Dictionary = {}
	for id in simulation.state.resources:
		var key: String = "resource/" + str(id)
		predicted[id] = float(initial[key]) + ticks * (float(first[key]) - float(initial[key]))
		if not is_finite(predicted[id]) or float(predicted[id]) < 0.0:
			trial_failure_reason = "predictor_resource_exhaustion"
			Checkpoint.restore(simulation, saved)
			return
	Checkpoint.restore(simulation, saved)
	for id in predicted:
		simulation.state.resources[id].amount = predicted[id]
	var before_probe: Dictionary = Metrics.numeric(simulation.state)
	super._advance(REFERENCE_STEP, end)
	var endpoint: Dictionary = Metrics.numeric(simulation.state)
	var result: Dictionary = {}
	for key in first:
		var base: float = float(initial.get(key, 0.0))
		var d0: float = float(first[key]) - base
		var d1: float = float(endpoint.get(key, 0.0)) - float(before_probe.get(key, 0.0))
		# For n=1 this is F_0.1 exactly. For n>1, the (n-1) correction
		# matches the n(n-1)/2 term of repeated discrete-map composition.
		result[key] = base + ticks * d0 + (ticks - 1.0) * 0.5 * (d1 - d0)
	for key in result:
		var value: float = float(result[key])
		if not is_finite(value) or (str(key).begins_with("resource/") and value < 0.0):
			trial_failure_reason = "corrector_resource_exhaustion"
			Checkpoint.restore(simulation, saved)
			return
		if (str(key).ends_with("total_produced") or str(key).ends_with("total_consumed") or str(key).ends_with("total_lost") or str(key).ends_with("/overflow") or str(key).ends_with("/decay")) and value < float(initial.get(key, 0.0)):
			trial_failure_reason = "negative_integrated_flow"
			Checkpoint.restore(simulation, saved)
			return
	Checkpoint.restore(simulation, saved)
	for id in simulation.state.resources:
		simulation.state.resources[id].amount = float(result["resource/" + str(id)])
	var objects: Array = [simulation.state.resource_statistics, simulation.state.current_run_statistics, simulation.state.simulation_statistics]
	var prefixes: Array[String] = ["lifetime", "run", "offline"]
	for index in range(objects.size()):
		var stats: ResourceStatistics = objects[index]
		if stats == null:
			continue
		var prefix: String = prefixes[index]
		stats.total_overflow = float(result[prefix + "/overflow"])
		stats.total_matter_decayed = float(result[prefix + "/decay"])
		for id in simulation.state.resources:
			var path: String = prefix + "/" + str(id) + "/"
			for field in ["total_produced", "total_consumed", "total_lost"]:
				if result.has(path + field):
					stats._ensure_resource(id)
					stats.statistics[id][field] = result[path + field]
			var peak_key: String = path + "highest_amount"
			if not first.has(peak_key):
				continue
			var peak: float = maxf(float(initial.get(peak_key, 0.0)), float(first[peak_key]))
			# Preserve reference microstep peaks, rather than recording the
			# fictitious lump production of a long Simulation.update(delta).
			if float(endpoint.get(peak_key, 0.0)) > float(initial.get(peak_key, 0.0)):
				var resource_key: String = "resource/" + str(id)
				var last_increment: float = float(endpoint[resource_key]) - float(before_probe[resource_key])
				peak = maxf(peak, float(endpoint[peak_key]) + float(result[resource_key]) - float(predicted[id]) - last_increment)
			stats._ensure_resource(id)
			stats.statistics[id]["highest_amount"] = peak
	simulation.state.total_overflow_this_prestige = float(result["reward/overflow"])
	simulation.state.total_matter_decayed_this_prestige = float(result["reward/decay"])

	simulation.state.set_lava_mite_dormancy_penalty(manager.get_dormancy_penalty(end))

