extends SceneTree
const Fixture = preload("res://tests/experimental/adaptive_benchmark.gd")
const Metrics = preload("res://tests/experimental/adaptive_metrics.gd")
const Checkpoint = preload("res://tests/experimental/continuous_checkpoint.gd")
class Segmented extends "res://tests/experimental/head_feedback.gd":
	var segment_ticks: int = 36000
	var last_tick: int = 0
	var last_fallback: int = 0
	var last_accepted: int = 0
	var segment_start: int = 0
	var previous: Dictionary = {}
	var widths: Array[float] = []
	func _sample(tick: int) -> void:
		if samples.has(tick):return
		if int(counters["accepted"]) > last_accepted:
			widths.append(float(tick - last_tick - (int(counters["fallback_ticks"]) - last_fallback)) * REFERENCE_STEP)
		last_accepted = counters["accepted"]
		last_fallback = counters["fallback_ticks"]
		last_tick = tick
		super(tick)
		if tick % segment_ticks != 0:return
		var now: int = Time.get_ticks_usec()
		var delta: Dictionary = {}
		for key in counters:
			if counters[key] is int:delta[key] = int(counters[key]) - int(previous.get(key, 0))
		widths.sort()
		var sum_width: float = 0.0
		for h in widths:sum_width += h
		print("SEGMENT_JSON " + JSON.stringify({"until": elapsed, "wall_seconds": float(now-segment_start)/1e6, "delta": delta, "coverage": sum_width/(float(segment_ticks)*REFERENCE_STEP), "average_step": sum_width/maxi(widths.size(),1), "median_step": widths[widths.size() >> 1] if not widths.is_empty() else 0.0, "max_step": widths[-1] if not widths.is_empty() else 0.0, "resources": Metrics.numeric(simulation.state, manager), "rejection_reasons": counters["rejection_reasons"], "fallback_reasons": counters["fallback_reasons"], "samples": samples.size()}))
		widths.clear();previous=counters.duplicate(true);segment_start=Time.get_ticks_usec()
func _initialize() -> void:call_deferred("_run")
func _run() -> void:
	var options: Dictionary = {"scenario":"feedback_stored","duration":"14400","execution":"adaptive"}
	for argument in OS.get_cmdline_user_args():
		var pair: PackedStringArray = argument.trim_prefix("--").split("=",true,1)
		if pair.size()==2:options[pair[0]]=pair[1]
	var state: GameState = Fixture.make_state(options["scenario"])
	var simulation := Simulation.new(state)
	var seconds: float = float(options["duration"])
	var start: int = Time.get_ticks_usec()
	if options["execution"] == "adaptive":
		var runner = Segmented.new(simulation)
		runner.segment_ticks = int(options.get("segment_ticks","36000"))
		runner.segment_start = start
		var result: Dictionary = runner.run(seconds)
		print("COMPLETE_JSON " + JSON.stringify({"phase":"adaptive","seconds":float(Time.get_ticks_usec()-start)/1e6,"counters":result,"discrete":Metrics.discrete(state),"rng":str(state.gameplay_rng.state)}))
	else:
		var manager := TimeManager.new(simulation)
		state.simulation_statistics=manager.simulation_statistics
		var last: int = start
		for tick in range(ceili(seconds/0.1)):
			var delta: float = minf(0.1,seconds-manager.game_time)
			manager.game_time+=delta;manager.offline_time+=delta;manager.prestige_time+=delta;manager.current_offline_duration+=delta
			state.set_lava_mite_dormancy_penalty(manager.get_dormancy_penalty(manager.game_time))
			simulation.update(delta,true)
			if (tick+1)%36000==0:
				var now: int = Time.get_ticks_usec()
				print("SEGMENT_JSON " + JSON.stringify({"until":manager.game_time,"wall_seconds":float(now-last)/1e6,"resources":Metrics.numeric(state,manager)}));last=Time.get_ticks_usec()
		print("COMPLETE_JSON " + JSON.stringify({"phase":"reference","seconds":float(Time.get_ticks_usec()-start)/1e6,"discrete":Metrics.discrete(state),"rng":str(state.gameplay_rng.state)}))
	quit()

